/**
 * Solandvolt - SEO espagnol des categories produit (titre, meta, OG) sur /es_es/
 * Complete l'extrait SEO espagnol : cible uniquement les categories product_cat.
 */
function sv_es_cat_seo( $text, $kind ) {
	global $TRP_LANGUAGE;
	if ( ! isset( $TRP_LANGUAGE ) || 'es_ES' !== $TRP_LANGUAGE || ! function_exists( 'is_tax' ) || ! is_tax( 'product_cat' ) ) {
		return $text;
	}
	$term = get_queried_object();
	if ( ! $term || empty( $term->term_id ) ) {
		return $text;
	}
	$map = array(
		20 => array( 'title' => 'Autonomía energética: kits solares'.' | Sol & Volt', 'desc' => 'Kits solares, baterías y estaciones de energía portátiles, en cuatro niveles de autonomía, sin obras. Envío a Francia y España.' ),
		21 => array( 'title' => 'La Veilleuse: lámparas y cargadores solares'.' | Sol & Volt', 'desc' => 'Lámparas, linternas, cargadores y paneles solares compactos para iluminar y recargar lo esencial durante un corte de luz. Envío a Francia y España.' ),
		33 => array( 'title' => 'El Módulo: estaciones, kits y paneles solares'.' | Sol & Volt', 'desc' => 'Estaciones de energía portátiles, paneles solares y kits listos para usar para mantener el router, la luz y los móviles durante un corte. Envío a Francia y España.' ),
		42 => array( 'title' => 'La Base: estaciones de energía y kits de balcón'.' | Sol & Volt', 'desc' => 'Estaciones de energía portátiles y kits solares de balcón para alimentar lo esencial de la casa. Envío a Francia y España.' ),
		50 => array( 'title' => 'La Autonomía: baterías solares para casa'.' | Sol & Volt', 'desc' => 'Baterías solares domésticas EcoFlow STREAM y kit solar Tornasol 800 W para producir y almacenar electricidad en casa. Envío a Francia y España.' ),
	);
	return isset( $map[ $term->term_id ][ $kind ] ) ? $map[ $term->term_id ][ $kind ] : $text;
}

foreach ( array(
	'rank_math/frontend/title' => 'title',
	'rank_math/opengraph/facebook/og_title' => 'title',
	'rank_math/opengraph/twitter/twitter_title' => 'title',
	'rank_math/frontend/description' => 'desc',
	'rank_math/opengraph/facebook/og_description' => 'desc',
	'rank_math/opengraph/twitter/twitter_description' => 'desc',
) as $hook => $kind ) {
	add_filter( $hook, function ( $t ) use ( $kind ) {
		return sv_es_cat_seo( $t, $kind );
	}, 100 );
}
